  [432222] = { nil, "Impaurito.", nil, 0x5a2205f2, "mu" },
  [432234] = { "Incidi sul tuo elmo la runa Onde di Marea:\n\n$I1\nQuando lanci Catena di Guarigione o Marea Gelida ottieni $N1 cariche di Onde di Marea, che riducono il tempo di lancio della tua Ondata di Cura del $N2%, riducono il tempo di lancio della tua Catena di Guarigione del $N3% e aumentano la probabilità di effetto critico della tua Ondata di Cura Inferiore del $N4%.", nil, 0x8a2b3c8f, nil, "um" },
  [432236] = { "Incidi sui tuoi bracciali la runa Rombo del Tuono:\n\n$I1\nDardo Fulminante e Catena di Fulmini hanno una probabilità del $N1% di aggiungere una carica al tuo Scudo di Fulmini attivo, fino a un massimo di $N2 cariche.\n\nFolgore della Terra ora rilascia tutte le cariche di Scudo di Fulmini oltre $N3, infliggendone i danni al bersaglio e restituendoti il $N4% del tuo mana massimo per ogni carica rilasciata.", nil, 0xe55dbaeb, nil, "um" },
  [432238] = { "Incidi sui tuoi bracciali la runa Folgore Statica:\n\n$I1\nIl tuo Scudo di Fulmini ora ha $N1 cariche e i tuoi attacchi in mischia hanno una probabilità del $N2% (del $N3% se combatti con due armi) di attivare una di queste cariche, danneggiando subito il bersaglio.", nil, 0x307f3a02, nil, "um" },
  [432241] = { "Incidi sui tuoi bracciali la runa Sovraccaricato:\n\n$I1\nIl tuo Scudo di Fulmini non perde mai cariche, ora ha un tempo di recupero di $D1 e infligge danni a tutti i nemici entro $N2 m.", nil, 0xa17d3e6e, nil, "um" },
  [432291] = { "Incidi sul tuo elmo la runa Attacchi Concentrati:\n\n$I1\nOttieni $N1 energia ogni volta che infliggi un colpo critico in mischia o a distanza.", nil, 0x8516edd3, nil, "um" },
  [432293] = { "Incidi sul tuo elmo la runa Efficienza Mancina:\n\n$I1\nHai una probabilità del $N1% di ottenere $N2 energia ogni volta che infliggi danni in mischia con l'arma secondaria.", nil, 0x495bf4a6, nil, "um" },
  [432295] = { "Incidi sul tuo elmo la runa Onore tra i Ladri:\n\n$I1\nQuando un giocatore del tuo gruppo infligge un colpo critico con un incantesimo o un'abilità, ottieni un punto combo sul bersaglio attuale. Questo effetto non può verificarsi più di una volta al secondo.", nil, 0x2bd127e7, nil, "um" },
  [432297] = { "Incidi sui tuoi bracciali la runa Prontezza in Mischia:\n\n$I1\nSventramento e Affondo Venefico rinnovano la durata di Fendenti Furiosi o di Lame Danzanti al massimo di $N1 punti combo. Se sono attivi entrambi, viene rinnovato solo quello con la durata residua più breve.", nil, 0x7d169149, nil, "um" },
  [432299] = { "Incidi sui tuoi bracciali la runa Carneficina:\n\n$I1\nLe tue abilità infliggono il $N1% di danni in più ai bersagli colpiti da uno dei tuoi effetti di sanguinamento. Perforazione inoltre ti cura del $N2% dei danni che infligge.", nil, 0xf0efc132, nil, "um" },
  [432301] = { "Incidi sui tuoi bracciali la runa Vantaggio Sleale:\n\n$I1\nOgni volta che schivi o pari un attacco ottieni Vantaggio Sleale, contrattaccando con il $N1% dei danni dell'arma principale e ottenendo $N2 punti combo. Questo effetto non può verificarsi più di una volta al secondo.", nil, 0xf11d0a7e, nil, "um" },
  [432308] = { nil, "Danni fisici inflitti ogni $D1.", nil, 0xc8fd5ef3, "mu" },
  [432639] = { "Aumenta la probabilità d'impatto del $N1%.", nil, 0x47acc177, nil, "um" },
